changeSet.sql:
ALTER TABLE usuarios ADD CONSTRAINT ck_usuarios_perfil
    CHECK (perfil IN ('JOGADOR', 'OBSERVADOR', 'ADMIN', 'SUPER', 'TESTE'));
ALTER TABLE tarefas ADD CONSTRAINT ck_tarefas_status
    CHECK (status IN ('FILA', 'LIBERADA', 'ESTIMADA', 'PULADA'));
ALTER TABLE tarefas ADD CONSTRAINT ck_tarefas_fase
    CHECK (fase IN ('PONTOS', 'PONTOS_REVELADOS', 'HORAS', 'HORAS_REVELADAS'));
ALTER TABLE tarefas ADD CONSTRAINT ck_tarefas_fase_horas_teste
    CHECK (fase_horas_teste IN ('VOTACAO', 'REVELADA'));
